package com.restpartijen.api.persistence

import com.restpartijen.api.shared.Role
import org.jetbrains.exposed.v1.core.Table
import org.jetbrains.exposed.v1.datetime.timestamp

/**
 * Table definition for user accounts (ERD §9.1, table USERS).
 *
 * Owner: Lonneke (GI-3). Lives in persistence because other features refer to it (issue #36).
 */
object UsersTable : Table("users") {
    /** The ID is the primary key and is generated by the database on insert. It is NEVER set by the application. */
    val id = long("id").autoIncrement()

    /** E-mail. This is also a Unique Key in the database. There cannot be another user with the same e-mail address. */
    val email = varchar("email", length = 255).uniqueIndex()

    /** Argon2id hash of the password (decision 3.4); the password itself is never stored. */
    val passwordHash = varchar("password_hash", length = 255)

    /** Name shown for the account. */
    val displayName = varchar("display_name", length = 255)

    /** Role stored by its name (for example "COLLECTOR"), read back as a Role. */
    val role = enumerationByName<Role>("role", length = 20)

    /** The moment the account was created. */
    val createdAt = timestamp("created_at")

    /** The moment the account was soft-deleted; null while it is active. A deleted account counts as not found. */
    val deletedAt = timestamp("deleted_at").nullable()

    // Tells Exposed (and the generated SQL) which column is the primary key.
    override val primaryKey = PrimaryKey(id)
}
